Here’s a minimal Flask login flow using Flask-Login and Werkzeug. The key point is to **store a password hash at registration** and verify the submitted password against that stored hash at login—don’t hash the submitted password again and compare hashes.

```bash
pip install Flask Flask-Login
```

```python
from flask import Flask, request, redirect, url_for, render_template_string
from flask_login import (
    LoginManager, UserMixin, current_user, login_required,
    login_user, logout_user,
)
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = "replace-with-a-long-random-secret"

login_manager = LoginManager(app)
login_manager.login_view = "login"

# Demo storage only. Use a database in a real application.
users = {}


class User(UserMixin):
    def __init__(self, user_id, password_hash):
        self.id = user_id
        self.password_hash = password_hash


@login_manager.user_loader
def load_user(user_id):
    password_hash = users.get(user_id)
    return User(user_id, password_hash) if password_hash else None


def hash_password(password):
    return generate_password_hash(password)


def validate_login(password, stored_hash):
    return check_password_hash(stored_hash, password)


@app.post("/register")
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")

    if not username or not password:
        return {"error": "Username and password are required."}, 400
    if username in users:
        return {"error": "Username already exists."}, 409

    users[username] = hash_password(password)
    return {"message": "Account created."}, 201


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "GET":
        return render_template_string("""
            <form method="post">
              <input name="username" autocomplete="username" required>
              <input name="password" type="password"
                     autocomplete="current-password" required>
              <button type="submit">Log in</button>
            </form>
        """)

    username = request.form.get("username", "").strip()
    password = request.form.get("password", "")
    stored_hash = users.get(username)

    if not stored_hash or not validate_login(password, stored_hash):
        return "Invalid username or password.", 401

    login_user(User(username, stored_hash))
    return redirect(url_for("dashboard"))


@app.get("/dashboard")
@login_required
def dashboard():
    return f"Logged in as {current_user.id}"


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))
```

The `users` dictionary is only for demonstrating the flow; it loses data when the app restarts. In your application, store each username and password hash in your database. For production, also use a securely generated secret key, HTTPS, and CSRF protection for form submissions.

