For your Flask budget tracker, the key is to verify the submitted password against the **hash stored when the user registered**—don’t hash the submitted password again during login.

Here’s a Flask-Login example using Flask-SQLAlchemy and Werkzeug. Adapt the `User` model to match your existing `users` table.

```python
import os

from flask import Flask, flash, redirect, render_template, request, url_for
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///budget_tracker.db"
app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]  # Set in your environment

db = SQLAlchemy(app)

login_manager = LoginManager(app)
login_manager.login_view = "login"
login_manager.login_message_category = "info"


class User(UserMixin, db.Model):
    __tablename__ = "users"

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


@login_manager.user_loader
def load_user(user_id):
    # Flask-Login passes IDs as strings.
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        user = db.session.execute(
            db.select(User).filter_by(username=username)
        ).scalar_one_or_none()

        if user is not None and check_password_hash(user.password_hash, password):
            login_user(user)
            return redirect(url_for("dashboard"))

        # Use the same message for an unknown username and a wrong password.
        flash("Invalid username or password.", "error")

    return render_template("login.html")


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


@app.route("/dashboard")
@login_required
def dashboard():
    return render_template("dashboard.html")
```

The password hash must be created and saved during registration, for example:

```python
from werkzeug.security import generate_password_hash

user.password_hash = generate_password_hash(password)
db.session.add(user)
db.session.commit()
```

A minimal `templates/login.html`:

```html
<form method="post" action="{{ url_for('login') }}">
  <label for="username">Username</label>
  <input id="username" name="username" autocomplete="username" required>

  <label for="password">Password</label>
  <input
    id="password"
    name="password"
    type="password"
    autocomplete="current-password"
    required
  >

  <button type="submit">Log in</button>
</form>

{% with messages = get_flashed_messages(with_categories=true) %}
  {% for category, message in messages %}
    <p role="alert">{{ message }}</p>
  {% endfor %}
{% endwith %}
```

For production, add CSRF protection to the form (for example, with Flask-WTF), use a long random `SECRET_KEY` supplied through your deployment environment, and serve the app over HTTPS. Keep the logout route as `POST` so it can be protected against CSRF as well.

